const digest=(bytes:Buffer)=>createHash('sha256').update(bytes).digest('hex');
function tree(root:string):readonly (readonly[string,string])[]{
 if(!existsSync(root))return [];
 const rows:[string,string][]=[];
 const visit=(at:string,relative:string)=>{for(const entry of readdirSync(at,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))){const path=join(at,entry.name),name=relative?relative+'/'+entry.name:entry.name;if(entry.isDirectory())visit(path,name);else{assert.ok(entry.isFile(),'signed sample has no links or special files');rows.push([name,digest(readFileSync(path))]);}}};
 visit(root,'');return rows;
}
function copySignedSample(dataset:string,target:string):void{
 const bytes=(name:string)=>samples?readFileSync(join(samples,dataset,name)):Buffer.from(signedSamples[dataset]![name]!);
 mkdirSync(target,{recursive:true});
 for(const name of ['TARGET.bound','packet.json','withdraw.json','refused-receipt.json'])writeFileSync(join(target,name),bytes(name));
 for(const child of ['catalog','inventory']){mkdirSync(join(target,child));writeFileSync(join(target,child,'TARGET.bound'),bytes(child+'/TARGET.bound'));}
}
for(const dataset of ['observed-words','inventory-colors'])test('native explicit Root contextual admission and act query '+dataset,{timeout:30000},()=>{
 const temp=mkdtempSync(join(tmpdir(),'bound-root-position-')),outside=join(temp,'outside'),root=join(temp,'acting'),other=join(temp,'other');mkdirSync(outside);
 try{
  copySignedSample(dataset,root);copySignedSample(dataset,other);
  const run=(args:string[])=>spawnSync(process.execPath,[cli,...args],{cwd:outside,env:{...process.env,NODE_OPTIONS:'',NODE_PATH:''},encoding:'utf8',timeout:10000,maxBuffer:1048576});
  // Actual CLI must select Root even though cwd contains no TARGET or ledger.
  const bootstrap=run(['land',root]);assert.equal(bootstrap.status,0,bootstrap.stderr);assert.ok(existsSync(join(root,'.bound','ledger')));assert.ok(!existsSync(join(outside,'.bound')));
  const packet=JSON.parse(readFileSync(join(root,'packet.json'),'utf8'));
  const admission=run(['land',root,join(root,'packet.json')]);assert.equal(admission.status,0,admission.stderr);const committed=JSON.parse(admission.stdout);assert.equal(committed.status,'landed');assert.equal(committed.context,packet.context);
  const query=run(['fold',root,'--as','act',committed.identity]);assert.equal(query.status,0,query.stderr);assert.equal(JSON.parse(query.stdout).context,packet.context);
  const replay=run(['land',root,join(root,'packet.json')]);assert.equal(replay.status,0,replay.stderr);assert.equal(JSON.parse(replay.stdout).status,'once');
  // Retained admission cannot authenticate a different supplied receipt.
  // The original act stays inspectable, but malformed replay must write nothing.
  const beforeTamperedReplay=tree(root);
  const tamperedReplay=run(['land',root,join(root,'refused-receipt.json')]);
  assert.notEqual(tamperedReplay.status,0,'replay validates the provided receiver signature before ONCE');
  assert.match(tamperedReplay.stderr,/REFUSE.*(receipt|signature|place-act)/);
  assert.deepEqual(tree(root),beforeTamperedReplay,'tampered committed replay must not change the Root');
  const retainedQuery=run(['fold',root,'--as','act',committed.identity]);assert.equal(retainedQuery.status,0,retainedQuery.stderr);assert.equal(retainedQuery.stdout,query.stdout);
  const beforeRoot=tree(root),beforeOther=tree(other),beforeOutside=tree(outside);
  const ambiguous=run(['land',root,other,join(root,'packet.json')]);assert.notEqual(ambiguous.status,0);assert.match(ambiguous.stderr,/REFUSE·root/);
  const ambiguousCheck=run(['fold',root,other,'--check']);assert.notEqual(ambiguousCheck.status,0);assert.match(ambiguousCheck.stderr,/REFUSE·root/);
  assert.deepEqual(tree(root),beforeRoot,'ambiguous Root must not change either store or public files');assert.deepEqual(tree(other),beforeOther);assert.deepEqual(tree(outside),beforeOutside);
  // A directory consumed as a valued flag operand is never a second Root.
  // The contextual envelope correctly refuses signing options, rather than
  // erroneously refusing two Roots or selecting the key-file directory.
  const valuedDirectory=run(['land','--key-file',other,root,join(root,'packet.json')]);assert.notEqual(valuedDirectory.status,0);assert.match(valuedDirectory.stderr,/contextual place accepts one already signed/);assert.doesNotMatch(valuedDirectory.stderr,/REFUSE·root/);
  assert.deepEqual(tree(other),beforeOther);
 }finally{rmSync(temp,{recursive:true,force:true});}
});
